21	// handleConnect handles a connect session for the given service.
22	func handleConnect(ctx context.Context, t Transport, service string, stdin io.Reader, stdout io.Writer) error {
23		refs, err := t.InfoRefs(ctx, service)
24		if err != nil {
25			return fmt.Errorf("connect %s info/refs: %w", service, err)
26		}
27		defer refs.Close()
28	
29		refReader := bufio.NewReader(refs)
30		var reply packp.SmartReply
31		if err := reply.Decode(refReader); err != nil {
32			return fmt.Errorf("parsing info/refs: %w", err)
33		}
34	
35		if _, err := io.Copy(stdout, refReader); err != nil {
36			return fmt.Errorf("streaming refs: %w", err)
37		}
38	
39		switch service {
40		case serviceUploadPack:
41			return handleFetch(ctx, t, stdin, stdout)
42		case serviceReceivePack:
43			// fall through
44		default:
45			return fmt.Errorf("unsupported service: %s", service)
46		}
47	
48		reqBody, err := gitproto.ReadReceivePackRequest(stdin)
49		if err != nil {
50			return fmt.Errorf("reading git request: %w", err)
51		}
52		reqBody, err = gitproto.AppendAgentToReceivePackRequest(reqBody, Agent)
53		if err != nil {
54			return fmt.Errorf("amending receive-pack agent: %w", err)
55		}
56		debuglog.Printf("git request: %d bytes", len(reqBody))
57	
58		if len(reqBody) == 0 {
59			return nil
60		}
61	
62		resp, err := t.ServiceRPC(ctx, service, bytes.NewReader(reqBody), func(req *http.Request) {
63			req.Header.Set("X-Entire-Push-Size", strconv.Itoa(len(reqBody)))
64		})
65		if err != nil {
66			return fmt.Errorf("connect %s POST: %w", service, err)
67		}
68		defer resp.Close()
69	
70		if _, err := io.Copy(stdout, resp); err != nil {
71			return fmt.Errorf("streaming response: %w", err)
72		}
73	
74		return nil
75	}
76	
77	// handleFetch handles upload-pack negotiation for connect mode by
78	// translating canonical git's stateful conversation into HTTP
79	// stateless-RPC requests against entire-server.
80	//
81	// Canonical git in connect mode acts as if it has a bidirectional
82	// pipe to git-upload-pack: wants + flush, then alternating have
83	// batches and server ACKs, terminated by done. HTTP smart-git is
84	// stateless: each POST to /git-upload-pack is independent and must
85	// carry the full wants list plus every have the client wants the
86	// server to consider.
87	//
88	// We bridge by buffering wants permanently, accumulating haves across
89	// rounds, and issuing one POST per have-batch flush. The server's
90	// real ACK/NAK response streams back to git, so git's MAX_IN_VAIN
91	// terminates on the first common ancestor instead of walking the
92	// entire rev queue. When git sends done, a final POST with the
93	// accumulated wants + haves + done streams the pack response.
94	//
95	// Shallow fetches add a probe round: if the wants section contains a
96	// `deepen…` line, canonical git parks waiting for the server's
97	// shallow/unshallow update before writing any haves. We fire an extra
98	// POST on the wants-flush carrying only the buffered wants, stream the
99	// shallow-update response to git, then resume the normal have/done
100	// flow. The wants buffer is preserved (every subsequent stateless-RPC
101	// round must repeat the wants block including the deepen lines, or the
102	// server treats the request as non-shallow).
103	func handleFetch(ctx context.Context, t Transport, stdin io.Reader, stdout io.Writer) error {
104		var wantsBuf, havesBuf bytes.Buffer
105		lenBuf := make([]byte, pktline.LenSize)
106		pastWants := false
107		deepenSeen := false
108		roundNumber := 0
109	
110		for {
111			_, err := io.ReadFull(stdin, lenBuf)
112			if err != nil {
113				if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
114					// Git closed stdin before done. Either it aborted or
115					// (more commonly) decided no fetch was needed before
116					// ever sending wants. Either way, exit cleanly.
117					return nil
118				}
119				return fmt.Errorf("reading pkt-line length: %w", err)
120			}
121	
122			pktLen, err := pktline.ParseLength(lenBuf)
123			if err != nil {
124				return fmt.Errorf("connect fetch: %w", err)
125			}
126	
127			if pktLen == pktline.Flush {
128				if !pastWants {
129					// End of wants section. Include the flush in the wants
130					// buffer (every request body needs it as the wants
131					// terminator) and switch to accumulating haves.
132					wantsBuf.Write(lenBuf)
133					pastWants = true
134					debuglog.Printf("end of wants (%d bytes)", wantsBuf.Len())
135					if deepenSeen {
136						if err := postShallowProbe(ctx, t, stdout, &wantsBuf); err != nil {
137							return err
138						}
139					}
140					continue
141				}
142				// End of a have batch. POST wants + cumulative haves +
143				// terminating flush so the server can compute ACKs.
144				roundNumber++
145				if err := postRound(ctx, t, stdout, &wantsBuf, &havesBuf, false, deepenSeen, roundNumber); err != nil {
146					return err
147				}
148				continue
149			}
150	
151			if pktLen < pktline.LenSize {
152				// Special pktlines (0001 delim, 0002 response-end) — not
153				// expected in v0/v1 client→server stream, but tolerate by
154				// pass-through to the appropriate buffer.
155				dest := &wantsBuf
156				if pastWants {
157					dest = &havesBuf
158				}
159				dest.Write(lenBuf)
160				continue
161			}
162	
163			content := make([]byte, pktLen-pktline.LenSize)
164			if _, err := io.ReadFull(stdin, content); err != nil {
165				return fmt.Errorf("reading pkt-line content: %w", err)
166			}
167	
168			// `deepen`, `deepen-since`, `deepen-not` in the wants section
169			// arm the probe POST on the upcoming wants-flush. `shallow X`
170			// from the client is purely informational (client telling the
171			// server about its existing shallow boundary) and does NOT
172			// trigger a server shallow-update unless paired with deepen,
173			// so it doesn't need a probe round.
174			if !pastWants && bytes.HasPrefix(content, []byte("deepen")) {
175				deepenSeen = true
176			}
177	
178			dest := &wantsBuf
179			if pastWants {
180				dest = &havesBuf
181			}
182			dest.Write(lenBuf)
183			dest.Write(content)
184	
185			if strings.TrimSpace(string(content)) == "done" {
186				// Final round: server returns ACK/NAK + pack data.
187				roundNumber++
188				debuglog.Printf("done line received, sending final request (round %d)", roundNumber)
189				return postRound(ctx, t, stdout, &wantsBuf, &havesBuf, true, deepenSeen, roundNumber)
190			}
191		}
192	}
193	
194	// postShallowProbe issues the shallow-update probe POST that canonical
195	// git in connect mode is waiting for after writing `wants + deepen +
196	// flush`. The body is exactly the buffered wants (already terminated
197	// by the wants-flush); the server response is `shallow…/unshallow…
198	// + flush` and is streamed verbatim to git's stdout. No synthetic NAK
199	// is appended — unlike intermediate have-batch rounds, the probe
200	// response IS the round terminator (its trailing flush) that git is
201	// waiting for, and appending NAK would confuse the client into
202	// thinking negotiation has already happened.
203	func postShallowProbe(ctx context.Context, t Transport, stdout io.Writer, wantsBuf *bytes.Buffer) error {
204		body, err := gitproto.AppendAgentToUploadPackRequest(append([]byte(nil), wantsBuf.Bytes()...), Agent)
205		if err != nil {
206			return fmt.Errorf("amending upload-pack agent: %w", err)
207		}
208		debuglog.Printf("posting shallow-update probe: %d bytes", len(body))
209		resp, err := t.ServiceRPC(ctx, serviceUploadPack, bytes.NewReader(body))
210		if err != nil {
211			return fmt.Errorf("shallow-update probe POST: %w", err)
212		}
213		defer resp.Close()
214		if _, err := io.Copy(stdout, resp); err != nil {
215			return fmt.Errorf("streaming shallow-update response: %w", err)
216		}
217		return nil
218	}
219	
220	// postRound assembles one stateless-RPC request body from the
221	// buffered wants and cumulative haves, posts it to /git-upload-pack,
222	// and streams the response back to git on stdout. Non-final rounds
223	// synthesize a trailing NAK pktline so canonical git in connect
224	// (stateful) mode doesn't hang waiting for the round-end marker that
225	// the HTTP wire drops implicitly.
226	//
227	// When stripShallow is true, the helper consumes the duplicate
228	// shallow/unshallow + flush prefix the server emits on every round
229	// that carries deepen in its body (HTTP stateless-RPC processes each
230	// POST independently — every response begins with the boundary
231	// section). Canonical git in connect mode only consumes the FIRST
232	// shallow response (fetch-pack.c:453-481); subsequent rounds enter
233	// the ACK/NAK loop directly, where a leftover "shallow X" pktline
234	// kills get_ack (fetch-pack.c:253: `expected ACK/NAK, got '%s'`).
235	func postRound(ctx context.Context, t Transport, stdout io.Writer, wantsBuf, havesBuf *bytes.Buffer, final, stripShallow bool, roundNumber int) error {
236		body := make([]byte, 0, wantsBuf.Len()+havesBuf.Len()+pktline.LenSize)
237		body = append(body, wantsBuf.Bytes()...)
238		body = append(body, havesBuf.Bytes()...)
239		if !final {
240			body = append(body, "0000"...)
241		}
242		debuglog.Printf("posting round %d: %d bytes (final=%v)", roundNumber, len(body), final)
243		body, err := gitproto.AppendAgentToUploadPackRequest(body, Agent)
244		if err != nil {
245			return fmt.Errorf("amending upload-pack agent: %w", err)
246		}
247	
248		resp, err := t.ServiceRPC(ctx, serviceUploadPack, bytes.NewReader(body))
249		if err != nil {
250			return fmt.Errorf("connect fetch round %d POST: %w", roundNumber, err)
251		}
252		defer resp.Close()
253	
254		var src io.Reader = resp
255		if stripShallow {
256			src, err = drainShallowUpdate(resp)
257			if err != nil {
258				return fmt.Errorf("draining shallow-update prefix on round %d: %w", roundNumber, err)
259			}
260		}
261	
262		if _, err := io.Copy(stdout, src); err != nil {
263			return fmt.Errorf("streaming round %d response: %w", roundNumber, err)
264		}
265		if !final {
266			if _, err := stdout.Write([]byte("0008NAK\n")); err != nil {
267				return fmt.Errorf("writing NAK terminator for round %d: %w", roundNumber, err)
268			}
269		}
270		return nil
271	}
272	
273	// drainShallowUpdate consumes a leading shallow/unshallow pktline run
274	// + the terminating flush from r and returns the trimmed reader. It is
275	// the stream-mirror of fetch-pack.c:205-223 `consume_shallow_list`,
276	// applied to intermediate AND final rounds in our connect-mode bridge
277	// because each have-round POST repeats `deepen` and the server
278	// dutifully re-emits the boundary section.
279	//
280	// If the first pktline isn't shallow/unshallow, returns r untouched —
281	// safe to call defensively on every shallow round even when the
282	// server (e.g. a probe-only response) happens to have no
283	// shallow-update prefix.
284	func drainShallowUpdate(r io.Reader) (io.Reader, error) {
285		br := bufio.NewReader(r)
286		for {
287			l, payload, err := pktline.PeekLine(br)
288			if err != nil {
289				if errors.Is(err, io.EOF) {
290					return br, nil
291				}
292				return nil, fmt.Errorf("peeking shallow-update pktline: %w", err)
293			}
294			if l == pktline.Flush {
295				if _, err := br.Discard(pktline.LenSize); err != nil {
296					return nil, fmt.Errorf("discarding shallow-update flush: %w", err)
297				}
298				return br, nil
299			}
300			if !bytes.HasPrefix(payload, []byte("shallow ")) &&
301				!bytes.HasPrefix(payload, []byte("unshallow ")) {
302				return br, nil
303			}
304			if _, err := br.Discard(l); err != nil {
305				return nil, fmt.Errorf("discarding shallow pktline: %w", err)
306			}
307		}
308	}
