// streamReadBufferSize is the per-connection socket read buffer. net/http
// defaults to 4 KiB, which is smaller than a TLS record (up to 16 KiB) and
// forces multiple read syscalls per record on the pack-stream hot path.
// 64 KiB lets one read pull a full TLS record and meaningfully reduces
// syscall + TLS-state-machine overhead during fetch.
const streamReadBufferSize = 64 << 10

// streamWriteBufferSize mirrors streamReadBufferSize on the write side. The
// helper's push path streams the packfile through the same transport, so the
// symmetry matters there too.
const streamWriteBufferSize = 64 << 10

// http2MaxReceiveBufferPerStream raises the HTTP/2 per-stream receive
// window. Go's bundled http2 transport defaults to 4 MiB, which caps a
// single-stream fetch at window/RTT — ~30 MB/s at 130 ms RTT, the original
// throttle. Git smart-HTTP fetch is one POST = one stream, so connection-
// level multiplexing buys nothing; widening the per-stream window is the
// only lever. 16 MiB lifts the ceiling to ~128 MB/s at the same RTT while
// staying well under reasonable memory budgets per concurrent fetch.
const http2MaxReceiveBufferPerStream = 16 << 20

// http2MaxReceiveBufferPerConnection scales the connection-level window
// alongside the per-stream window. Go's default is already 1 GiB, but
// HTTP2Config requires both bounds set together to take effect; matching
// 4× the per-stream budget keeps the connection from becoming the cap
// even if a future caller multiplexes pack streams.
const http2MaxReceiveBufferPerConnection = 64 << 20

// NewTransport builds an *http.Transport with the configured dial timeout
// and a baseline TLS config. Callers wrap the returned transport with their
// own RoundTripper as needed (e.g. debug logging) and assemble their own
// *http.Client around it.
//
// ForceAttemptHTTP2 is set because net/http's auto-HTTP/2 path bails out
// conservatively whenever a custom DialContext or TLSClientConfig is present
// (see (*http.Transport).protocols in Go's stdlib) — and we set both. Without
// this flag the transport advertises only http/1.1 in ALPN and every caller
// (the data-plane Proxy in internal/remotehelper/transport, the bootstrap
// client in git-remote-entire, the cluster well-known probe, the login-JWT
// refresh provider, and the repo-scoped token exchange) is pinned to
// HTTP/1.1. http.DefaultTransport itself sets ForceAttemptHTTP2 for the same
// reason; we mirror that here.
//
// ReadBufferSize / WriteBufferSize, HTTP2Config, and DisableCompression are
// all tuned for the pack-stream hot path — see the corresponding constants
// for the math.
func NewTransport(skipTLSVerify bool) *http.Transport {
	return &http.Transport{
		ForceAttemptHTTP2: true,
		ReadBufferSize:    streamReadBufferSize,
		WriteBufferSize:   streamWriteBufferSize,
		// Pack data is already deflate-compressed at the object level, so
		// transparent HTTP-layer gzip is pure CPU tax for zero size win.
		// Drop the Accept-Encoding: gzip header (and the decoder code path)
		// so the read loop hands bytes straight to git.
		DisableCompression: true,
		HTTP2: &http.HTTP2Config{
			MaxReceiveBufferPerStream:     http2MaxReceiveBufferPerStream,
			MaxReceiveBufferPerConnection: http2MaxReceiveBufferPerConnection,
		},
		DialContext: (&net.Dialer{Timeout: DialTimeout()}).DialContext,
		TLSClientConfig: &tls.Config{
			MinVersion:         tls.VersionTLS12,
			InsecureSkipVerify: skipTLSVerify, //nolint:gosec // intentional for local development
		},
	}
}

