// refresh provider, and the repo-scoped token exchange) is pinned to
// HTTP/1.1. http.DefaultTransport itself sets ForceAttemptHTTP2 for the same
// reason; we mirror that here.
func NewTransport(skipTLSVerify bool) *http.Transport {
	return &http.Transport{
		ForceAttemptHTTP2: true,
		DialContext:       (&net.Dialer{Timeout: DialTimeout()}).DialContext,
		TLSClientConfig: &tls.Config{
			MinVersion:         tls.VersionTLS12,
			InsecureSkipVerify: skipTLSVerify, //nolint:gosec // intentional for local development
		},
	}
}

