// TestNewTransport_PackStreamTuning pins the throughput-oriented knobs
// that make the pack stream actually use the link. These are easy to
// silently drop in a future cleanup ("looks like style noise") and the
// only symptom is fetch bandwidth quietly regressing back to <30 MB/s on
// high-RTT links, so a structural pin is cheaper than detecting it from
// downstream perf benchmarks.
func TestNewTransport_PackStreamTuning(t *testing.T) {
	t.Parallel()
	tr := NewTransport(false)

	if tr.ReadBufferSize != streamReadBufferSize {
		t.Errorf("ReadBufferSize=%d, want %d", tr.ReadBufferSize, streamReadBufferSize)
	}
	if tr.WriteBufferSize != streamWriteBufferSize {
		t.Errorf("WriteBufferSize=%d, want %d", tr.WriteBufferSize, streamWriteBufferSize)
	}
	if !tr.DisableCompression {
		t.Error("DisableCompression=false, want true (pack data is pre-compressed)")
	}
	if tr.HTTP2 == nil {
		t.Fatal("HTTP2 config is nil; expected per-stream / per-conn receive buffers")
	}
	if tr.HTTP2.MaxReceiveBufferPerStream != http2MaxReceiveBufferPerStream {
		t.Errorf("HTTP2.MaxReceiveBufferPerStream=%d, want %d",
			tr.HTTP2.MaxReceiveBufferPerStream, http2MaxReceiveBufferPerStream)
	}
	if tr.HTTP2.MaxReceiveBufferPerConnection != http2MaxReceiveBufferPerConnection {
		t.Errorf("HTTP2.MaxReceiveBufferPerConnection=%d, want %d",
			tr.HTTP2.MaxReceiveBufferPerConnection, http2MaxReceiveBufferPerConnection)
	}
}

